import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { UserService } from 'src/app/services/emis/user.service';

@Component({
  selector: 'app-class-section',
  templateUrl: './class-section.page.html',
  styleUrls: ['./class-section.page.scss'],
})
export class ClassSectionPage implements OnInit {
  routeData: any;
  SchlId: any;

  constructor(private router: Router, private route: ActivatedRoute, private userService: UserService) { }

  ngOnInit() {

  }

  ionViewDidEnter() {
    this.routeData = this.route.snapshot;
    this.SchlId = this.routeData.queryParams.SchlId;
    this.userService.getAllClassList(2, '3509').subscribe(res => {
      if (res) {
        console.log(res)
      }
    });
  }


  onGoButton() {
    this.router.navigate(['/tabs/school-list-mht'])
  }

  
  navigateToClass() {
    this.router.navigate(['/tabs/section-list-mht'])
  }
}
